import React, { useState, useRef, useEffect } from 'react';
import { Lock, Mail, ArrowRight, Eye, EyeOff, Activity, ShieldAlert } from 'lucide-react';

const SignIn = () => {
  const [showPassword, setShowPassword] = useState(false);
  const [dragX, setDragX] = useState(0);
  const [isAuthorized, setIsAuthorized] = useState(false);
  const sliderRef = useRef(null);
  const isDragging = useRef(false);

  // Constants for the slider math
  const HANDLE_WIDTH = 80;
  const TRACK_PADDING = 12;

  const handleStart = () => { isDragging.current = true; };

  const handleMove = (e) => {
    if (!isDragging.current || isAuthorized) return;
    const clientX = e.touches ? e.touches[0].clientX : e.clientX;
    const rect = sliderRef.current.getBoundingClientRect();

    // Calculate position inside the track
    let x = clientX - rect.left - (HANDLE_WIDTH / 2);

    // Constrain the handle within the button boundaries
    const maxX = rect.width - HANDLE_WIDTH - (TRACK_PADDING * 2);
    x = Math.max(0, Math.min(x, maxX));

    setDragX(x);

    // If they swipe more than 95% of the way, authorize them
    if (x > maxX * 0.95) {
      setDragX(maxX);
      setIsAuthorized(true);
      isDragging.current = false;
      // You can trigger your login logic here
    }
  };

  const handleEnd = () => {
    if (isAuthorized) return;
    isDragging.current = false;
    setDragX(0); // Snap back if not fully swiped
  };

  useEffect(() => {
    window.addEventListener('mousemove', handleMove);
    window.addEventListener('mouseup', handleEnd);
    window.addEventListener('touchmove', handleMove);
    window.addEventListener('touchend', handleEnd);
    return () => {
      window.removeEventListener('mousemove', handleMove);
      window.removeEventListener('mouseup', handleEnd);
      window.removeEventListener('touchmove', handleMove);
      window.removeEventListener('touchend', handleEnd);
    };
  }, [dragX, isAuthorized]);

  return (
    <div className="flex flex-col items-center justify-center p-6 animate-slot">
      <div className="w-full max-w-[460px] flex flex-col">

        {/* HEADER */}
        <div className="bg-[#AB1717] border-[6px] border-[#47510B] rounded-t-[40px] p-8 red-stack-shadow relative z-20">
          <div className="flex items-center gap-5">
            <div className="bg-[#FDFAD8] p-3 rounded-xl border-4 border-[#47510B]">
              <ShieldAlert size={32} className="text-[#AB1717]" />
            </div>
            <h1 className="text-3xl font-black italic text-[#FDFAD8] uppercase">
              TRASH<span className="text-[#CAD23C]">2</span>TRACK
            </h1>
          </div>
        </div>

        {/* INPUT DECK (BLENDED) */}
        <div className="bg-transparent border-x-[6px] border-[#47510B] p-10 flex flex-col gap-8 relative z-10">
          <input type="email" placeholder="IDENTITY" className="w-full bg-white border-[5px] border-[#47510B] p-6 rounded-[20px] font-black text-xl outline-none shadow-[6px_6px_0_0_#47510B] uppercase" />
          <div className="relative">
            <input type={showPassword ? "text" : "password"} placeholder="PASSPHRASE" className="w-full bg-white border-[5px] border-[#47510B] p-6 rounded-[20px] font-black text-xl outline-none shadow-[6px_6px_0_0_#47510B]" />
            <button onClick={() => setShowPassword(!showPassword)} className="absolute right-6 top-6 text-[#47510B] opacity-40">
              {showPassword ? <EyeOff size={22} /> : <Eye size={22} />}
            </button>
          </div>
        </div>

        {/* THE SWIPE-TO-OPEN BUTTON (Horizontal Track) */}
        <div 
          ref={sliderRef}
          className="bg-[#AB1717] border-[6px] border-[#47510B] rounded-b-[40px] p-[12px] red-stack-shadow relative z-20 h-28 flex items-center select-none overflow-hidden"
        >
          {/* Shimmering background text */}
          <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
            <span className={`text-xl font-black uppercase tracking-[0.3em] animate-shimmer transition-opacity duration-300 ${dragX > 20 ? 'opacity-0' : 'opacity-100'}`}>
              Slide to Unlock
            </span>
          </div>

          {/* THE HANDLE (The original yellow arrow button now slides) */}
          <div 
            onMouseDown={handleStart}
            onTouchStart={handleStart}
            style={{ 
              transform: `translateX(${dragX}px)`,
              transition: isDragging.current ? 'none' : 'transform 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275)'
            }}
            className={`w-20 h-20 bg-[#CAD23C] border-4 border-[#47510B] rounded-[20px] flex items-center justify-center cursor-grab active:cursor-grabbing shadow-[4px_4px_0_0_#47510B] relative z-30`}
          >
            <ArrowRight size={32} className="text-[#47510B]" strokeWidth={4} />
          </div>

          {/* SUCCESS OVERLAY */}
          {isAuthorized && (
            <div className="absolute inset-0 bg-[#CAD23C] flex items-center justify-center animate-pulse z-40">
              <span className="text-[#47510B] font-black text-2xl italic uppercase tracking-tighter">ACCESS GRANTED</span>
            </div>
          )}
        </div>

        <p className="text-center text-[10px] font-black uppercase tracking-[0.5em] text-[#AB1717] opacity-40 mt-6 italic">Secure.Node.V3</p>
      </div>
    </div>
  );
};

export default SignIn;
